import axios from "axios";
import { useEffect, useState } from "react";

const UnifiedActionSection = ({ onOpenLogin }) => {
  const [stats, setStats] = useState({
    totalCentres: 0,
    totalPackages: 0,
    totalServices: 0,
    totalDoctors: 0
  });

  const fetchStats = async () => {
    try {
      const res = await axios.get(
        `${process.env.REACT_APP_BACKEND_URL}/api/admin/stats`
      );
      if (res.status === 200) setStats(res.data);
    } catch (err) {
      console.error("Error fetching stats:", err);
    }
  };

  useEffect(() => {
    fetchStats();
  }, []);

  return (
    <div className="unified-action-section overflow-hidden position-relative z-index-1">
      <div className="unified-premium-card p-4 p-xl-5 rounded-4 shadow-premium-lg">
        <div className="row gy-5 align-items-center">
          {/* Stats Side */}
          <div className="col-lg-6 pr-lg-5">
            <div className="section-content mb-40">
              <span className="subtitle-unified">Why People Trust Us</span>
              <h2 className="unified-title mb-3">Your Health, Our Priority</h2>
              <p className="unified-desc text-muted">
                Join thousands who trust 4Ceps for verified healthcare, easy bookings, 
                and professional care management.
              </p>
            </div>

            <div className="row g-3 stats-grid-unified">
              <div className="col-6 col-sm-3 col-lg-6">
                <div className="stat-card-mini">
                  <div className="mini-icon blue"><i className="fas fa-clinic-medical"></i></div>
                  <div className="mini-content">
                    <h4>{stats.totalCentres}</h4>
                    <span>Centres</span>
                  </div>
                </div>
              </div>
              <div className="col-6 col-sm-3 col-lg-6">
                <div className="stat-card-mini">
                  <div className="mini-icon orange"><i className="fas fa-medkit"></i></div>
                  <div className="mini-content">
                    <h4>{stats.totalPackages}</h4>
                    <span>Packages</span>
                  </div>
                </div>
              </div>
              <div className="col-6 col-sm-3 col-lg-6">
                <div className="stat-card-mini">
                  <div className="mini-icon green"><i className="fas fa-microscope"></i></div>
                  <div className="mini-content">
                    <h4>{stats.totalServices}</h4>
                    <span>Services</span>
                  </div>
                </div>
              </div>
              <div className="col-6 col-sm-3 col-lg-6">
                <div className="stat-card-mini">
                  <div className="mini-icon purple"><i className="fas fa-user-md"></i></div>
                  <div className="mini-content">
                    <h4>{stats.totalDoctors}</h4>
                    <span>Doctors</span>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Registration Side */}
          <div className="col-lg-6 border-start-lg">
            <div className="registration-content pl-lg-5">
              <div className="info-block mb-4">
                <h4 className="info-title"><i className="fas fa-user-injured mr-10 blue-text"></i> For Patients</h4>
                <p className="info-text">
                  Book appointments, view medical reports, and manage family health 
                  records in one secure place. Free and easy to use.
                </p>
              </div>

              <div className="info-block mb-48">
                <h4 className="info-title"><i className="fas fa-hospital mr-10 orange-text"></i> For Healthcare Centres</h4>
                <p className="info-text">
                  Grow your practice, manage appointments digitally, and build 
                  trust with patients across the city.
                </p>
              </div>

              <div className="cta-wrapper text-center text-lg-start">
                <button 
                  onClick={onOpenLogin}
                  className="btn btn-main btn-xl pill fw-700 px-5 shadow-main-lg hover-up"
                >
                  Login / Sign Up
                </button>
                <p className="mt-3 small text-muted">Join the 4Ceps community today — it's free!</p>
              </div>
            </div>
          </div>
        </div>
      </div>

      <style>
{`
  .unified-premium-card {
    background: #ffffff;
    border: 1px solid rgba(0,0,0,0.05);
    background: linear-gradient(135deg, #ffffff 0%, #faffff 100%);
    position: relative;
  }

  .shadow-premium-lg {
    box-shadow: 0 15px 50px rgba(0,0,0,0.08);
  }

  .subtitle-unified {
    color: #B9322C;
    text-transform: uppercase;
    letter-spacing: 2px;
    font-size: 13px;
    font-weight: 700;
    margin-bottom: 15px;
    display: block;
  }

  .unified-title {
    font-size: 42px;
    font-weight: 800;
    color: #1e293b;
    line-height: 1.2;
  }

  .unified-desc {
    font-size: 16px;
    line-height: 1.6;
    max-width: 480px;
  }

  .stat-card-mini {
    background: #fff;
    padding: 15px;
    border-radius: 16px;
    display: flex;
    align-items: center;
    gap: 12px;
    border: 1px solid rgba(0,0,0,0.03);
    transition: all 0.3s ease;
  }

  .stat-card-mini:hover {
    transform: translateY(-3px);
    box-shadow: 0 5px 15px rgba(0,0,0,0.05);
  }

  .mini-icon {
    width: 40px;
    height: 40px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
  }

  .mini-icon.blue { background: rgba(13, 110, 253, 0.1); color: #0d6efd; }
  .mini-icon.orange { background: rgba(241, 101, 34, 0.1); color: #F16522; }
  .mini-icon.green { background: rgba(25, 135, 84, 0.1); color: #198754; }
  .mini-icon.purple { background: rgba(102, 16, 242, 0.1); color: #6610f2; }

  .mini-content h4 { font-size: 18px; font-weight: 700; color: #1e293b; margin: 0; line-height: 1.2; }
  .mini-content span { font-size: 11px; color: #94a3b8; text-transform: uppercase; font-weight: 600; }

  .border-start-lg { border-left: 1px solid rgba(0,0,0,0.05); }

  .info-title { font-size: 20px; font-weight: 700; margin-bottom: 10px; display: flex; align-items: center; color: #1e293b; }
  .info-text { font-size: 15px; color: #64748b; line-height: 1.5; margin: 0; }
  
  .blue-text { color: #0d6efd; }
  .orange-text { color: #F16522; }
  .mr-10 { margin-right: 10px; }

  .shadow-main-lg { box-shadow: 0 10px 25px rgba(241, 101, 34, 0.25); }
  .hover-up { transition: all 0.3s ease; }
  .hover-up:hover { transform: translateY(-5px); box-shadow: 0 15px 30px rgba(241, 101, 34, 0.35); }

  @media (max-width: 991px) {
    .border-start-lg { border-left: none; border-top: 1px solid rgba(0,0,0,0.05); padding-top: 2rem; }
    .pl-lg-5 { padding-left: 0 !important; }
    .unified-title { font-size: 32px; }
  }

  @media (max-width: 575px) {
    .unified-premium-card { padding: 1.5rem !important; }
    .unified-title { font-size: 28px; }
    .stat-card-mini { padding: 10px; }
    .mini-content h4 { font-size: 16px; }
  }
`}
</style>
    </div>
  );
};

export default UnifiedActionSection;
